// Initialize distances
for (int i = 0; i < n; i++) {
    dist[i] = (i == start) ? 0 : INT_MAX;
}

// Create a set to store vertices that are being processed
std::set<std::pair<int, int>> pq;  // {distance, vertex}
pq.insert({0, start});

// While there are vertices to process
while (!pq.empty()) {
    // Get the vertex with the smallest distance
    int u = pq.begin()->second;
    pq.erase(pq.begin());

    // Update distances for all adjacent vertices
    for (int v = 0; v < n; v++) {
        if (graph[u][v] && dist[u] != INT_MAX && dist[u] + graph[u][v] < dist[v]) {
            // If a shorter path is found
            pq.erase({dist[v], v});
            dist[v] = dist[u] + graph[u][v];
            pq.insert({dist[v], v});
        }
    }
}

